/**
 * The author seat — the one thing the chain needs from a model.
 *
 * The seat is mocked at this boundary, not at the provider wire: the model
 * layer sits beneath a production implementation and no chain code changes
 * when it arrives. The author call carries no tools; the root stays
 * clean (https://chain.smithers.sh/contract/).
 *
 * @since 0.1.0
 */
import * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Ref from "effect/Ref";
import * as Schema from "effect/Schema";
import * as Effect_1 from "effect/Effect";
/**
 * A failure of the author seat: the seat is unreachable, or a scripted mock
 * ran out of outputs.
 *
 * @category errors
 * @since 0.1.0
 * @slop
 */
export class AuthorError extends Schema.TaggedError()("/chain/AuthorError", {
    code: Schema.Literals(["author_unavailable", "exhausted"]),
    message: Schema.String,
    /**
     * The underlying typed condition when one exists — a model failure code
     * (`rate_limited`, `context_overflow`), a permission tag, or a stop
     * reason (`length`, `content-filter`) — so callers branch on it rather
     * than parsing prose.
     */
    cause: Schema.optional(Schema.String)
}) {
}
/**
 * Normalizes an author call's payload into its context lines: scripts call
 * the author entry with `{ context: [...] }`, and anything else — a script
 * passing garbage stays a journaled observation, never a crash — normalizes
 * to no context.
 * Context elements use string coercion, falling back to JSON text when
 * coercion fails, or `[unprintable context]` if serialization also fails.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const contextOf = (payload) => {
    if (typeof payload === "object" && payload !== null && "context" in payload) {
        const context = payload.context;
        if (Array.isArray(context)) {
            return context.map((part) => {
                try {
                    return String(part);
                }
                catch {
                    try {
                        return JSON.stringify(part) ?? "[unprintable context]";
                    }
                    catch {
                        return "[unprintable context]";
                    }
                }
            });
        }
    }
    return [];
};
/**
 * The author seat service tag.
 *
 * @category services
 * @since 0.1.0
 * @slop
 */
export class Author extends Context.Service()("/chain/Author") {
}
/**
 * Builds a seat from an implementation.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const make = (implementation) => Author.of(implementation);
/**
 * A seat whose every operation fails as unavailable, with per-operation
 * overrides — the default a test starts from.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const makeNoop = (overrides = {}) => make({
    author: Effect.fn("Author.author")(() => Effect.fail(new AuthorError({ code: "author_unavailable", message: "author is unavailable" }))),
    ...overrides
});
/**
 * The unavailable seat as a layer.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerNoop = (overrides = {}) => Layer.succeed(Author)(makeNoop(overrides));
/**
 * A reactive mock: the test supplies the function from input to raw model
 * output, and can capture the inputs it saw.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerFn = (f) => Layer.succeed(Author)(make({
    author: Effect.fn("Author.author")((input) => Effect_1.sync(() => { return f(input); }))
}));
/**
 * A scripted mock: pops canned raw outputs in order and fails with
 * `exhausted` when asked for more than it holds. The outputs are copied
 * when the layer is constructed, so a later edit of the caller's array
 * changes nothing.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerMock = (outputs) => {
    // Snapshot now, not when the lazy layer is later built: a caller may
    // mutate its array after constructing the layer but before providing it.
    const snapshot = [...outputs];
    return Layer.effect(Author)(Effect_1.gen(function* () {
        const remaining = yield* Ref.make(snapshot);
        return make({
            author: Effect.fn("Author.author")(Effect_1.fnUntraced(function* () {
                const next = yield* Ref.modify(remaining, (queue) => [queue[0], queue.slice(1)]);
                if (next === undefined) {
                    return yield* Effect_1.fail(new AuthorError({
                        code: "exhausted",
                        message: `the mock author ran out of outputs after ${snapshot.length}`
                    }));
                }
                return next;
            }))
        });
    }));
};

/**
 * The catalog of entries a script may call — gate 3 is membership in it.
 *
 * Every effect goes through this one door: a call names a visible entry,
 * pinned by its declaration digest, and settles as a journaled event
 * (https://chain.smithers.sh/contract/).
 *
 * @since 0.1.0
 */
import * as Digest from "@smthrs/core/Digest";
import { Clock, Context, Layer, Random, Schema } from "effect";
/**
 * A call that reached its entry and failed there. The chain journals it as
 * an observation rather than crashing the run. The message is journaled
 * verbatim and shown to the model on the next link, so a handler must keep
 * credentials and private data out of it.
 *
 * @category errors
 * @since 0.1.0
 * @slop
 */
export class CallError extends Schema.TaggedError()("/chain/CallError", {
    name: Schema.String,
    message: Schema.String,
    /**
     * The underlying stable code when the failing subsystem has one (a
     * memory error code, a permission verdict), so callers branch on it
     * rather than parsing prose.
     */
    cause: Schema.optional(Schema.String)
}) {
}
/**
 * The catalog service tag.
 *
 * @category services
 * @since 0.1.0
 * @slop
 */
export class Catalog extends Context.Service()("/chain/Catalog") {
}
/**
 * The declaration digest that pins an entry's identity into every call key
 * that names it.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const entryDigest = (entry) => 
// An empty override falls back too: every call key pins a non-empty
// digest, whatever the host supplied. Declared capabilities are part
// of the declaration: narrowing or widening a claim re-keys the calls
// settled under it.
entry.digest !== undefined && entry.digest !== ""
    ? entry.digest
    : Digest.digest(Digest.canonical({
        capabilities: entry.capabilities ?? null,
        description: entry.description,
        name: entry.name
    }));
/**
 * One entry copied out of the caller's object.
 *
 * The outer array is not enough. `Prompt.catalogBlock` reads `entries` and
 * gate 3 reads `lookup`, and both must keep answering about the SAME
 * declaration: renaming a caller-owned entry after construction would leave
 * the block advertising one name while the index still answers to another.
 * Only the declaration is copied — the handler is the entry's behavior and is
 * held by reference.
 */
const snapshotEntry = (entry) => Object.freeze({
    capabilities: entry.capabilities === undefined ? undefined : Object.freeze([...entry.capabilities]),
    description: entry.description,
    digest: entry.digest,
    handler: entry.handler,
    settleOnInterrupt: entry.settleOnInterrupt,
    name: entry.name
});
/**
 * Builds a catalog over the given entries, indexed by name.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const make = (entries) => {
    // One frozen snapshot backs BOTH the advertised list and the dispatch
    // index. Retaining the caller's array would let a later push or pop move
    // `Prompt.catalogBlock` (which reads `entries`) away from `lookup` (which
    // gate 3 decides membership with), so the model would be shown a call the
    // chain refuses, or refused a call the model was never shown.
    const snapshot = Object.freeze(entries.map(snapshotEntry));
    const byName = new Map(snapshot.map((entry) => [entry.name, entry]));
    return Catalog.of({
        entries: snapshot,
        lookup: (name) => byName.get(name)
    });
};
/**
 * The system entries every sealed realm relies on: time and randomness as
 * ordinary journaled calls, so replay is deterministic with no special
 * identity (https://chain.smithers.sh/contract/).
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const system = [
    {
        // The empty claim set is deliberate: these are the harness's own
        // journaled reads, claiming no external authority, so the envelope
        // seam has nothing to evaluate and every ruleset admits them.
        capabilities: [],
        description: "The current wall-clock time in epoch milliseconds, journaled for replay",
        handler: () => Clock.currentTimeMillis,
        name: "sys/now"
    },
    {
        capabilities: [],
        description: "A uniform random number in [0, 1), journaled for replay",
        handler: () => Random.next,
        name: "sys/random"
    }
];
/**
 * Appends the system entries to a host's own — the composition every
 * sealed-realm host wants, since the QuickJS prelude deletes `Date` and
 * `Math.random` on the promise that `sys/now` and `sys/random` exist.
 *
 * The system entries come LAST because {@link make} indexes last-wins:
 * nothing a host passes can shadow `sys/now` or `sys/random` with an
 * unjournaled clock or RNG, which is what replay determinism rests on.
 * Every composition in the package goes through here, so the ordering has
 * one implementation rather than one per host.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const withSystem = (entries) => [...entries, ...system];
/**
 * The empty catalog: every call misses gate 3.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const makeNoop = () => make([]);
/**
 * A catalog over the given entries, as a layer.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layer = (entries) => Layer.succeed(Catalog)(make(entries));
/**
 * The empty catalog as a layer.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerNoop = Layer.succeed(Catalog)(makeNoop());

/**
 * The authored artifact of one link: flow-script text plus its content
 * digest.
 *
 * The digest is the replay identity of every call the script makes
 * (https://chain.smithers.sh/contract/). Extraction implements gate 1
 * (shape): the author's output must contain exactly one fenced flow block.
 *
 * @since 0.1.0
 */
import * as Schema from "effect/Schema";
import * as Digest from "@smthrs/core/Digest";
/**
 * A link's flow-script text paired with the content digest that keys every
 * call it makes.
 *
 * @category models
 * @since 0.1.0
 * @slop
 */
export const Script = Schema.Struct({
    text: Schema.String,
    digest: Schema.String
});
/**
 * Builds a script from its text, digesting it.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const make = (text) => ({ text, digest: Digest.digest(text) });
// Closes the way a markdown fence closes: on a line holding only a run of
// backticks at least as long as the opening run, plus trailing blanks. A
// lazy match on any "\n```" would end the block at an inner "```js" line
// inside a template literal and hand the runner a truncated script.
const fence = /(?<!`)(`{3,})flow\n([\s\S]*?)\n\1`*[ \t]*(?=\n|$)/g;
/**
 * Applies the shape gate to raw author output: exactly one fenced `flow`
 * block, whose body becomes the script. The block opens with three or more
 * backticks followed by `flow` and closes on a line holding only at least
 * as many backticks, so a longer opening fence can carry inner fences.
 * CRLF line endings are read as LF, so the script text always uses LF.
 *
 * @category gates
 * @since 0.1.0
 * @slop
 */
export const extract = (raw) => {
    // Some routes return CRLF text; the fence only knows LF line ends.
    const blocks = [...raw.replace(/\r\n/g, "\n").matchAll(fence)];
    const first = blocks[0];
    if (first === undefined) {
        return { _tag: "Rejected", reason: "the author output contains no ```flow block" };
    }
    if (blocks.length > 1) {
        return {
            _tag: "Rejected",
            reason: `the author output contains ${blocks.length} \`\`\`flow blocks, expected exactly one`
        };
    }
    // The capture group always participates when the fence matches.
    return { _tag: "Extracted", script: make(first[2]) };
};

/**
 * The journal event vocabulary of a chain, and the pure folds over it.
 *
 * The journal is the only state. The call cache used for replay, the
 * observation context handed to recovery author calls, and the terminal
 * verdict are all pure folds over the event array — nothing else is stored
 * anywhere (https://chain.smithers.sh/contract/).
 *
 * @since 0.1.0
 */
import * as Schema from "effect/Schema";
import * as CallKey from "./CallKey.js";
import * as Observation from "./Observation.js";
import * as Outcome from "./Outcome.js";
import * as Script from "./Script.js";
/**
 * The chain a scoped event belongs to. Omitted at the root — existing
 * journals stay byte-identical — and set to the deterministic child id
 * (`parent-chain/link.ordinal`) for sub-chain events.
 *
 * @category models
 * @since 0.1.0
 */
const scoped = { chain: Schema.optional(Schema.String) };
/**
 * The chain's first event: the goal it was started with and the caller's
 * envelope.
 *
 * @category models
 * @since 0.1.0
 * @slop
 */
export const ChainStarted = Schema.TaggedStruct("ChainStarted", {
    ...scoped,
    goal: Schema.String,
    envelope: Schema.Json
});
/**
 * The script a link will execute, recorded before it runs so a resumed link
 * replays the same source.
 *
 * @category models
 * @since 0.1.0
 * @slop
 */
export const LinkAuthored = Schema.TaggedStruct("LinkAuthored", {
    ...scoped,
    link: CallKey.LinkId,
    script: Script.Script
});
/**
 * One call that reached an entry and produced a result — the unit the
 * replay cache is keyed by.
 *
 * @category models
 * @since 0.1.0
 * @slop
 */
export const CallSettled = Schema.TaggedStruct("CallSettled", {
    ...scoped,
    link: CallKey.LinkId,
    key: CallKey.CallKey,
    name: Schema.String,
    payload: Schema.Json,
    result: Schema.Json
});
/**
 * One call a gate refused, recorded as the observation the next authoring
 * reads.
 *
 * @category models
 * @since 0.1.0
 * @slop
 */
export const GateRejected = Schema.TaggedStruct("GateRejected", {
    ...scoped,
    link: CallKey.LinkId,
    ordinal: CallKey.Ordinal,
    observation: Observation.Observation
});
/**
 * The outcome a link ended with — the event that advances the link counter.
 *
 * @category models
 * @since 0.1.0
 * @slop
 */
export const LinkEnded = Schema.TaggedStruct("LinkEnded", {
    ...scoped,
    link: CallKey.LinkId,
    outcome: Outcome.Outcome
});
/**
 * One non-empty steering drain, tied to the live author call it fed —
 * a nondeterministic boundary in the sense of `RecordBoundary`
 * (packages/smithers/agent/harness/src/EngineLike.ts), journaled so a re-executed attempt reuses the recorded lines. Empty
 * drains are not journaled: a settled author call already pins its
 * context in its `CallSettled` payload.
 *
 * @category models
 * @since 0.1.0
 * @slop
 */
export const SteeringDrained = Schema.TaggedStruct("SteeringDrained", {
    ...scoped,
    link: CallKey.LinkId,
    ordinal: CallKey.Ordinal,
    messages: Schema.Array(Schema.String)
});
/**
 * Every event a chain can journal.
 *
 * @category models
 * @since 0.1.0
 * @slop
 */
export const Event = Schema.Union([ChainStarted, LinkAuthored, CallSettled, GateRejected, LinkEnded, SteeringDrained]);
/**
 * Whether an event belongs to the given chain scope.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const inChain = (event, chain) => (event.chain ?? "") === chain;
/**
 * Whether the chain has recorded its `ChainStarted` event.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const started = (events, chain = "") => events.some((event) => event._tag === "ChainStarted" && inChain(event, chain));
/**
 * The index of the current link: links end strictly in order, so the count
 * of `LinkEnded` events names the link now in progress.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const linkCount = (events, chain = "") => events.filter((event) => event._tag === "LinkEnded" && inChain(event, chain)).length;
/**
 * The script authored for a link, if any. Link 0 (bootstrap) never has one.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const authored = (events, link, chain = "") => {
    for (const event of events) {
        if (event._tag === "LinkAuthored" && event.link === link && inChain(event, chain))
            return event.script;
    }
    return undefined;
};
/**
 * The settled calls of a link, keyed by ordinal — the replay cache.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const settled = (events, link, chain = "") => {
    const calls = new Map();
    for (const event of events) {
        if (event._tag === "CallSettled" && event.link === link && inChain(event, chain)) {
            calls.set(event.key.ordinal, event);
        }
    }
    return calls;
};
/**
 * The gate rejections of a link, keyed by ordinal — replayed as aborts so a
 * resumed link never re-executes a rejected call.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const rejected = (events, link, chain = "") => {
    const rejections = new Map();
    for (const event of events) {
        if (event._tag === "GateRejected" && event.link === link && inChain(event, chain)) {
            rejections.set(event.ordinal, event);
        }
    }
    return rejections;
};
/**
 * All observations recorded for a link, in journal order — the material a
 * recovery author call projects into its context.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const observations = (events, link, chain = "") => events.flatMap((event) => event._tag === "GateRejected" && event.link === link && inChain(event, chain) ? [event.observation] : []);
/**
 * Every steering line recorded for a link, in drain order. Steering is
 * link-cumulative: once drained into a link it reaches every subsequent
 * author attempt of that link, so a rejected attempt never swallows the
 * user's instruction.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const steeringLines = (events, link, chain = "") => events.flatMap((event) => event._tag === "SteeringDrained" && event.link === link && inChain(event, chain) ? event.messages : []);
/**
 * The ordinals of a link's recorded drains — a resumed execution never
 * re-drains a boundary it already consumed.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const steeredOrdinals = (events, link, chain = "") => new Set(events.flatMap((event) => event._tag === "SteeringDrained" && event.link === link && inChain(event, chain) ? [event.ordinal] : []));
/**
 * The chain's terminal outcome, if it has one: the last `LinkEnded` whose
 * outcome is `Done` or `Park`. A replay of a finished chain returns this
 * without executing anything.
 *
 * @category folds
 * @since 0.1.0
 * @slop
 */
export const terminal = (events, chain = "") => {
    const last = [...events].reverse().find((event) => event._tag === "LinkEnded" && inChain(event, chain));
    if (last === undefined)
        return undefined;
    return last.outcome._tag === "To" ? undefined : last.outcome;
};

/**
 * The typed failure bridge between recursive runs and catalog handlers.
 *
 * @since 0.1.0
 */
import * as Catalog from "../Catalog.js";
/**
 * Carries a child run's original typed failure across the catalog boundary.
 *
 * @private
 * @since 0.1.0
 */
export class ChildRunError extends Catalog.CallError {
    error;
    constructor(error) {
        super({ cause: error.code, message: `${error._tag}: ${error.message}`, name: "agent" });
        this.error = error;
    }
}

/**
 * The append-only journal port — the chain's only state.
 *
 * The in-memory layer is a deletable stand-in for the Smithers engine journal:
 * the e2e suite asserts journal contents, not this API, so the suite
 * survives the engine swap (https://chain.smithers.sh/contract/).
 *
 * @since 0.1.0
 */
import * as Effect_1 from "effect/Effect";
import * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";
/**
 * A journal that cannot be appended to or read.
 *
 * @category errors
 * @since 0.1.0
 * @slop
 */
export class JournalError extends Schema.TaggedError()("/chain/JournalError", {
    code: Schema.Literals(["journal_conflict", "journal_unavailable"]).pipe(Schema.withConstructorDefault(Effect.succeed("journal_unavailable"))),
    message: Schema.String
}) {
}
/**
 * The journal service tag.
 *
 * @category services
 * @since 0.1.0
 * @slop
 */
export class Journal extends Context.Service()("/chain/Journal") {
}
/**
 * Builds a journal from an implementation.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const make = (implementation) => Journal.of(implementation);
const unavailable = (operation) => new JournalError({ message: `${operation} is unavailable` });
/**
 * A journal whose every operation fails as unavailable, with per-operation
 * overrides — the default a test starts from.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const makeNoop = (overrides = {}) => make({
    append: Effect.fn("Journal.append")(() => Effect.fail(unavailable("append"))),
    read: Effect.fail(unavailable("read")),
    ...overrides
});
/**
 * The unavailable journal as a layer.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerNoop = (overrides = {}) => Layer.succeed(Journal)(makeNoop(overrides));
/**
 * An in-memory journal over one array, optionally seeded with prior events —
 * the seed is how tests replay and resume a chain. Appends push in place and
 * reads hand out a copy, so a reader never sees a later append and an append
 * never copies the history.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerMemory = (initial = []) => {
    // Snapshot now, not when the lazy layer is later built: a caller may
    // mutate its seed after constructing the layer but before providing it.
    const snapshot = [...initial];
    return Layer.sync(Journal)(() => {
        // Copy per build, so two builds of one layer never share a history.
        const events = [...snapshot];
        return make({
            append: Effect.fn("Journal.append")((event, expectedPosition) => Effect.suspend(() => {
                if (events.length !== expectedPosition) {
                    return Effect.fail(new JournalError({
                        code: "journal_conflict",
                        message: `append expected journal position ${expectedPosition}, found ${events.length}`
                    }));
                }
                events.push(event);
                return Effect.void;
            })),
            read: Effect_1.sync({ read: () => events.slice() }.read)
        });
    });
};

/**
 * The steering port: messages from outside the chain, drained at link
 * boundaries into author-call context.
 *
 * The port is shaped so the notifications package's durable queue slots
 * in as the production binding when the engine mounts; the in-memory
 * layer is the stand-in. Chains that provide no steering service run
 * unchanged and journal identically — the chain looks the service up
 * optionally (https://chain.smithers.sh/contract/).
 *
 * @since 0.1.0
 */
import * as Context from "effect/Context";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Ref from "effect/Ref";
import * as Schema from "effect/Schema";
import * as Effect_1 from "effect/Effect";
/**
 * A steering queue that cannot be admitted to or drained.
 *
 * @category errors
 * @since 0.1.0
 * @slop
 */
export class SteeringError extends Schema.TaggedError()("/chain/SteeringError", {
    code: Schema.Literal("steering_unavailable").pipe(Schema.withConstructorDefault(Effect.succeed("steering_unavailable"))),
    message: Schema.String
}) {
}
/**
 * The steering service tag.
 *
 * @category services
 * @since 0.1.0
 * @slop
 */
export class Steering extends Context.Service()("/chain/Steering") {
}
/**
 * Builds a steering port from an implementation.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const make = (implementation) => Steering.of(implementation);
const unavailable = (operation) => new SteeringError({ message: `${operation} is unavailable` });
/**
 * A steering port whose every operation fails as unavailable, with
 * per-operation overrides — the default a test starts from.
 *
 * @category constructors
 * @since 0.1.0
 * @slop
 */
export const makeNoop = (overrides = {}) => make({
    admit: Effect.fn("Steering.admit")(() => Effect.fail(unavailable("admit"))),
    drain: Effect.fn("Steering.drain")(() => Effect.fail(unavailable("drain"))),
    ...overrides
});
/**
 * The unavailable steering port as a layer.
 *
 * @category layers
 * @since 0.1.0
 * @slop
 */
export const layerNoop = (overrides = {}) => Layer.succeed(Steering)(makeNoop(overrides));
/**
 * An in-memory steering queue: `admit` appends, `drain` takes everything.
 *
 * @category layers
 * @since 0.1.0
 * @slop
